export const PROMO_CSS = '\n.dialog-title{flex:1;display:flex;flex-direction:column;gap:2px;padding-top:2px}\n.dialog-title h3{padding-top:0}\n.dialog-eyebrow{font-weight:600;font-size:13px;line-height:1.4;color:var(--mp-violet-text)}\n.promo-icon{flex:none;display:flex;align-items:center;justify-content:center;border-radius:12px;overflow:hidden;\n background:var(--mp-raised);border:1px solid var(--mp-line-strong);color:var(--mp-violet-text);font-weight:800;font-size:26px}\n.promo-icon[data-size="56"]{width:56px;height:56px}.promo-icon[data-size="72"]{width:72px;height:72px}\n.promo-icon img{width:100%;height:100%;object-fit:cover}\n.promo-meta{display:flex;flex-direction:column;gap:2px;min-width:0}\n.promo-meta strong{font-size:17px;line-height:1.3}\n.promo-meta small{font-size:13px;font-weight:600;line-height:1.4;color:var(--mp-text-3)}\n.promo-badge{align-self:flex-start;height:20px;padding:0 6px;border-radius:6px;background:var(--mp-mint);\n color:var(--mp-on-accent);font-weight:700;font-size:12px;line-height:20px}\n.promo-network{display:flex;align-items:center;gap:8px;font-weight:600;font-size:13px;color:var(--mp-text-3)}\n.promo-install{height:48px;width:100%}\n.promo-slot{position:fixed;inset:0;z-index:20;display:grid;grid-template-rows:63fr 37fr;background:var(--mp-window-background);color:var(--mp-text)}\n.promo-stage{position:relative;display:flex;align-items:center;justify-content:center;background:var(--mp-navy);\n border-bottom:1px solid var(--mp-line);overflow:hidden}\n.promo-video{width:min(300px,80%);aspect-ratio:5/6;display:flex;align-items:center;justify-content:center;\n border:1px dashed var(--mp-line-strong);border-radius:16px;overflow:hidden;color:var(--mp-text-2)}\n.promo-video>*{max-width:100%;max-height:100%}\n.promo-progress{position:absolute;left:0;right:0;top:0;height:4px;background:var(--mp-surface)}\n.promo-progress>svg{display:block;width:100%;height:100%;fill:var(--mp-violet)}\n\n.promo-progress>[data-part=icon]{display:block;width:100%;height:100%;fill:var(--mp-violet)}\n.promo-bar{position:absolute;left:16px;right:16px;top:56px;display:flex;justify-content:space-between;align-items:center}\n.promo-tag{display:flex;align-items:center;gap:8px;height:32px;padding:0 12px 0 8px;border-radius:8px;\n background:var(--mp-window-background);border:1px solid var(--mp-line);font-size:13px;font-weight:600}\n.promo-skip{min-height:44px;height:44px;padding:0 14px;border-radius:8px;background:var(--mp-window-background);\n border:1px solid var(--mp-line);color:var(--mp-text-2);font-size:13px}\n.promo-skip:disabled{opacity:1;cursor:default}\n.promo-skip b{min-width:24px;height:24px;border-radius:8px;background:var(--mp-surface);color:var(--mp-text);\n display:inline-flex;align-items:center;justify-content:center}\n.promo-panel{background:var(--mp-navy);padding:24px 16px 32px;display:flex;flex-direction:column;gap:16px;min-height:0}\n.promo-game{display:flex;align-items:center;gap:16px;padding:12px;border-radius:12px;background:var(--mp-surface);\n border:1px solid var(--mp-line)}\n.promo-game .promo-meta{flex:1}.promo-game .promo-meta strong{font-size:22px;font-weight:600}\n.promo-rate{display:flex;align-items:center;gap:6px;font-size:13px;font-weight:600;color:var(--mp-text-2)}\n.promo-rate b{color:var(--mp-text);font-weight:700}\n.promo-text{color:var(--mp-text-2)}\n.promo-bonus{display:flex;flex-direction:column;gap:16px}\n.promo-cta{height:64px;min-height:64px;font-size:22px;font-weight:700}\n.promo-gift{border-radius:12px;background:var(--mp-surface);border:1px solid var(--mp-line);padding:16px;\n display:grid;grid-template-columns:repeat(3,1fr);gap:8px}\n.promo-gift-item{display:flex;flex-direction:column;align-items:center;gap:8px;min-width:0;text-align:center}\n.promo-gift-art{width:72px;height:72px;border-radius:12px;background:var(--mp-navy);border:1px solid var(--mp-line);\n display:flex;align-items:center;justify-content:center;overflow:hidden;font-weight:600;font-size:11px;color:var(--mp-text-3)}\n.promo-gift-item strong{font-size:15px}.promo-gift-item small{margin-top:-8px;font-size:13px;font-weight:600;color:var(--mp-text-3)}\n.promo-points{color:var(--mp-gold)}\n.promo-lead{display:flex;align-items:center;gap:16px}.promo-lead strong{font-size:20px;line-height:1.25}\n.promo-lives-status{display:flex;flex-direction:column;align-items:center;gap:8px;order:1}\n.promo-lives-art{width:72px;height:72px;border-radius:16px;background:var(--mp-surface);border:1px solid var(--mp-line);\n display:flex;align-items:center;justify-content:center}\n.promo-lives-timer{display:flex;align-items:center;gap:8px;color:var(--mp-text-2);font-weight:600}\n.promo-lives-timer b{color:var(--mp-text);font-weight:700}\n.promo-lives-cols,.promo-lives-left,.promo-lives-right{display:contents}\n.promo-card{order:2;border-radius:12px;background:var(--mp-surface);border:1px solid var(--mp-line);padding:16px;\n display:flex;flex-direction:column;gap:12px}\n.promo-card .promo-lead{gap:12px}\n.promo-ad{order:3;width:100%}\n.promo-lives-foot{order:4;display:flex;flex-direction:column;align-items:center}\n.promo-lives-foot .promo-network{order:2}\n.dialog button.promo-decline{height:44px;min-height:44px;background:transparent;color:var(--mp-text-2);border:0}\n.dialog button.promo-decline:not(:disabled):hover{background:transparent;color:var(--mp-text)}\n@media (orientation:landscape) and (max-height:520px){\n .promo-slot{grid-template-rows:none;grid-template-columns:1fr 1fr}\n .promo-stage{border-bottom:0;border-right:1px solid var(--mp-line)}\n .promo-video{width:min(360px,80%);aspect-ratio:36/23}\n .promo-stage{position:static}\n .promo-progress{top:auto;bottom:0;right:50%}\n .promo-bar{position:static}\n .promo-tag{position:absolute;left:16px;top:16px}\n .promo-skip{position:absolute;right:16px;top:16px;white-space:nowrap}\n .promo-panel{padding:76px 24px 20px;justify-content:flex-start}\n .promo-cta{margin-top:auto}\n .dialog:has(.promo-lives-cols){width:min(620px,100%)}\n .dialog:has(.promo-bonus){width:min(680px,100%);display:grid;grid-template-columns:220px 1fr;\n  grid-template-rows:auto auto auto 1fr;gap:12px 24px;padding:20px 24px}\n .dialog:has(.promo-bonus)>.dialog-head{grid-column:2;grid-row:1}\n .dialog:has(.promo-bonus)>.promo-bonus{grid-column:1;grid-row:1/5;align-items:center;justify-content:center;\n  text-align:center;padding:16px;gap:12px;border-radius:12px;background:var(--mp-surface);border:1px solid var(--mp-line)}\n .promo-bonus .promo-lead{flex-direction:column;gap:12px}\n .promo-bonus .promo-text{font-size:13px;font-weight:600}\n .dialog:has(.promo-bonus)>.promo-gift{grid-column:2;grid-row:2;padding:12px 16px;gap:8px}\n .promo-gift-item{display:grid;grid-template-columns:48px 1fr;grid-template-rows:auto auto;column-gap:8px;row-gap:0;\n  align-items:center;text-align:left}\n .promo-gift-art{grid-row:1/3;width:48px;height:48px;font-size:10px}.promo-gift-art img{width:40px;height:40px}\n .promo-gift-item small{margin-top:0}\n .dialog:has(.promo-bonus)>.window-actions{grid-column:2;grid-row:3}\n .dialog:has(.promo-bonus)>.promo-network{grid-column:2;grid-row:4;justify-self:center;align-self:end}\n .promo-lives-cols{display:flex;gap:16px;min-height:0}\n .promo-lives-left{display:flex;flex-direction:column;align-items:center;gap:8px;width:220px;flex:none;\n  border-radius:12px;background:var(--mp-surface);border:1px solid var(--mp-line);padding:16px}\n .promo-lives-left .promo-lives-status{order:0}\n .promo-lives-left .promo-ad{margin-top:auto}\n .promo-lives-right{display:flex;flex-direction:column;gap:12px;flex:1;min-width:0}\n .promo-lives-right .promo-card{flex:1;justify-content:space-between}\n .promo-lives-foot{flex-direction:row;justify-content:space-between;width:100%}\n .promo-lives-foot .promo-network{order:0}\n .promo-lives-timer{display:grid;grid-template-columns:auto auto;justify-content:center;align-items:center;\n  column-gap:6px;color:var(--mp-text-3);font-size:13px}\n .promo-lives-timer>span{grid-column:1/3;grid-row:1}\n .promo-lives-timer>svg{grid-row:2;grid-column:1;width:20px;height:20px;color:var(--mp-text-2)}\n\n .promo-lives-timer>[data-part=icon]{grid-row:2;grid-column:1;width:20px;height:20px;color:var(--mp-text-2)}\n .promo-lives-timer>b{grid-row:2;grid-column:2;font-size:22px;line-height:1}\n}';
